package br.com.pacto.recrutamento.infra.templatevaga;
import javax.persistence.*; import java.time.OffsetDateTime; import java.util.UUID;
@Entity @Table(name="requisitos_template_vaga") public class RequisitoTemplateVagaJpaEntity { @Id private UUID id; @Column(name="template_vaga_id",nullable=false) private UUID templateVagaId; @Column(nullable=false,columnDefinition="TEXT") private String descricao; @Column(nullable=false) private boolean obrigatorio; @Column(name="criado_em",nullable=false) private OffsetDateTime criadoEm; @Column(name="atualizado_em",nullable=false) private OffsetDateTime atualizadoEm; @Column(name="excluido_em") private OffsetDateTime excluidoEm; protected RequisitoTemplateVagaJpaEntity(){} RequisitoTemplateVagaJpaEntity(UUID i,UUID t,String d,boolean o,OffsetDateTime c,OffsetDateTime a,OffsetDateTime x){id=i;templateVagaId=t;descricao=d;obrigatorio=o;criadoEm=c;atualizadoEm=a;excluidoEm=x;} @PrePersist void incluir(){OffsetDateTime n=OffsetDateTime.now();if(criadoEm==null)criadoEm=n;atualizadoEm=n;} @PreUpdate void atualizar(){atualizadoEm=OffsetDateTime.now();} UUID getId(){return id;} UUID getTemplateVagaId(){return templateVagaId;} String getDescricao(){return descricao;} boolean isObrigatorio(){return obrigatorio;} OffsetDateTime getCriadoEm(){return criadoEm;} OffsetDateTime getAtualizadoEm(){return atualizadoEm;} OffsetDateTime getExcluidoEm(){return excluidoEm;} }
